import json, sys

def kind(value):
    if value is None: return "null"
    if isinstance(value, bool): return "boolean"
    if isinstance(value, str): return "string"
    if isinstance(value, dict): return "object"
    if isinstance(value, list): return "array"
    if isinstance(value, int): return "integer"
    return "number"

def serialized(value, ascii_only):
    try:
        return json.dumps(value, separators=(",", ":"), ensure_ascii=ascii_only), ""
    except Exception as exc:
        return "", str(exc)

facts = {"jsonValid":False,"documentKind":"invalid","error":"","errorType":"","objectGetError":"","compactJson":"","asciiJson":"","serializeError":"","fields":{}}
config = json.loads(sys.argv[2])
for key in config:
    facts["fields"][key] = {"present":False,"kind":"missing","text":"","pythonText":"None","pythonTextError":"","json":"null","asciiJson":"null","serializeError":"","isTrue":False,"isFalse":False,"truthy":False,"objectGetError":""}
try:
    payload = json.loads(sys.argv[1])
    facts["jsonValid"], facts["documentKind"] = True, kind(payload)
    if not isinstance(payload, dict):
        try: payload.get("_inspection")
        except Exception as exc: facts["objectGetError"] = str(exc)
    facts["compactJson"], facts["serializeError"] = serialized(payload, False)
    facts["asciiJson"], _ = serialized(payload, True)
    for key, path in config.items():
        value, present = payload, True
        for segment in path:
            if isinstance(value, list) and type(segment) is int and 0 <= segment < len(value):
                value = value[segment]
            elif isinstance(value, dict) and segment in value:
                value = value[segment]
            else:
                present = False
                break
        if not present: continue
        field = facts["fields"][key]
        field.update(present=True, kind=kind(value), text=value if isinstance(value,str) else "", isTrue=value is True, isFalse=value is False, truthy=bool(value))
        if not isinstance(value, dict):
            try: value.get("_inspection")
            except Exception as exc: field["objectGetError"] = str(exc)
        try: field["pythonText"] = str(value)
        except Exception as exc: field["pythonTextError"] = str(exc)
        field["json"], field["serializeError"] = serialized(value, False)
        field["asciiJson"], _ = serialized(value, True)
except Exception as exc:
    facts["error"] = str(exc)
    facts["errorType"] = type(exc).__name__
factsJson = json.dumps(facts, separators=(",", ":"), ensure_ascii=False)
